package com.library.model;
public class Book { private long bookId,categoryId; private String isbn,bookName,author,publisher,shelfNumber,status,categoryName; private int publicationYear,quantity,availableQuantity; public long getBookId(){return bookId;} public void setBookId(long v){bookId=v;} public long getCategoryId(){return categoryId;} public void setCategoryId(long v){categoryId=v;} public String getIsbn(){return isbn;} public void setIsbn(String v){isbn=v;} public String getBookName(){return bookName;} public void setBookName(String v){bookName=v;} public String getAuthor(){return author;} public void setAuthor(String v){author=v;} public String getPublisher(){return publisher;} public void setPublisher(String v){publisher=v;} public String getShelfNumber(){return shelfNumber;} public void setShelfNumber(String v){shelfNumber=v;} public String getStatus(){return status;} public void setStatus(String v){status=v;} public String getCategoryName(){return categoryName;} public void setCategoryName(String v){categoryName=v;} public int getPublicationYear(){return publicationYear;} public void setPublicationYear(int v){publicationYear=v;} public int getQuantity(){return quantity;} public void setQuantity(int v){quantity=v;} public int getAvailableQuantity(){return availableQuantity;} public void setAvailableQuantity(int v){availableQuantity=v;} @Override public String toString(){return bookName+" ("+isbn+")";} }
